// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    // Allow this contract (the bank) to receive the fee transfer.
    receive() external payable {}

    function testFuzz_property(address actor, uint256 t) public {
        // Admissible domain: a real external caller, distinct from the contract itself.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // Fuzz the randomness inputs (timestamp feeds the pseudo-random win check).
        vm.warp(t);

        // Exactly one ticket purchase by the fuzzed caller.
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: after play, the pot is either fully paid out (0)
        // or still holds a full accumulated ticket (>= TICKET_AMOUNT).
        // The mutant stores 1 instead of 10 after a losing round, breaking this.
        assertTrue(c.pot() == 0 || c.pot() >= 10);
    }
}
